--
-- Estructura de tabla para la tabla `ventas`
--

CREATE TABLE `ventas` (
  `id` int(10) UNSIGNED NOT NULL,
  `id_usuario` int(10) UNSIGNED NOT NULL COMMENT 'Cajero que realizó la venta',
  `id_medio_pago` tinyint(3) UNSIGNED NOT NULL,
  `tipo_comprobante` enum('SIMPLE','BOLETA','FACTURA') NOT NULL DEFAULT 'SIMPLE',
  `serie` varchar(4) DEFAULT NULL COMMENT 'B001 / F001',
  `correlativo` int(8) UNSIGNED ZEROFILL DEFAULT NULL COMMENT '00000001',
  `numero_comprobante` varchar(13) GENERATED ALWAYS AS (concat(coalesce(`serie`,''),'-',lpad(coalesce(`correlativo`,0),8,'0'))) STORED COMMENT 'B001-00000001 (calculado)',
  `tipo_doc_cliente` enum('DNI','RUC','CE','PASAPORTE','SIN_DOC') NOT NULL DEFAULT 'SIN_DOC',
  `documento_cliente` varchar(15) DEFAULT NULL,
  `nombre_cliente` varchar(150) NOT NULL DEFAULT 'Público General',
  `direccion_cliente` varchar(250) DEFAULT NULL COMMENT 'Requerido en FACTURA',
  `moneda` char(3) NOT NULL DEFAULT 'PEN' COMMENT 'PEN / USD',
  `subtotal` decimal(12,2) NOT NULL COMMENT 'Base imponible sin IGV',
  `igv` decimal(12,2) NOT NULL DEFAULT 0.00 COMMENT '18%',
  `total` decimal(12,2) NOT NULL,
  `estado_emision` enum('BORRADOR','EMITIDO','ACEPTADO_SUNAT','RECHAZADO_SUNAT','ANULADO') NOT NULL DEFAULT 'BORRADOR',
  `cdr_respuesta` text DEFAULT NULL,
  `hash_cpe` varchar(100) DEFAULT NULL COMMENT 'Hash SHA-1 del XML',
  `xml_firmado` longtext DEFAULT NULL COMMENT 'XML CDR de SUNAT',
  `fecha_emision` date DEFAULT NULL,
  `fecha_creacion` timestamp NOT NULL DEFAULT current_timestamp(),
  `fecha_actualizacion` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

